// Test stub for SvelteKit's virtual `$app/paths` module. The real module is
// generated by `sveltekit()` at build time; under vitest we only use the
// `svelte()` plugin, so we alias `$app/paths` to this stub. The base path is ''
// in tests, matching the default (root) deployment, so `resolve(pathname)` is
// '/' followed by the pathname, as SvelteKit's own `resolve` returns it.
export function resolve(pathname: string): string {
	return `/${pathname}`;
}
